@page {
    size: 176mm 250mm;
    margin: 0;
}

body {
    width: 176mm;
    height: 250mm;
    margin-left: 35px;
    margin-right: 35px;
    padding-right: 30px;
    padding-left: 30px;
    background-image: url(/files/backgroundForm.png);
    background-size: cover;
    background-repeat: no-repeat;
    font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
}

.print-format {
    margin: 0;
    padding: 25px;
    background-color: transparent;
    direction: rtl;
    color: #000;
    height: 100%;
    display: flex;
    flex-direction: column;
    justify-content: top; /* Vertically center content */
    align-items: center;     /* Horizontally center */
}

/* --- Header --- */
.header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    margin-bottom: 25px;
    padding-bottom: 15px;
    border-bottom: 2px solid #4472c4;
}

.header .paragraph {
    font-size: 18px;
    font-weight: bold;
    margin: 3px 0;
    line-height: 1.4;
}

.header .header-right .paragraph {
    text-align: right;
}

.header .header-left .paragraph {
    text-align: right;
    direction: ltr;
}

.header img {
    height: 80px;
    margin: 0 auto;
}

/* --- Horizontal Rule --- */
hr {
    width: 95%;
    margin: 20px auto;
    border: 0;
    border-top: 1px solid #4472c4;
}

/* --- Number & Date Section --- */
.number-date {
    width: 100%;
    text-align: right;
    direction: ltr;
    margin-bottom: 20px;
    padding: 10px 0;
    border-bottom: 1px dashed #ccc;
}

.number-date .paragraph {
    display: inline-block;
    margin: 0 15px 0 0;
    font-size: 16px;
    font-weight: bold;
}

/* --- Title --- */
.title {
    text-align: center;
    color: #d90429; /* Deep red — official & urgent tone */
    font-size: 26px;
    font-weight: bold;
    margin: 25px 0;
    text-transform: uppercase;
    letter-spacing: 1px;
    text-shadow: 1px 1px 2px rgba(0,0,0,0.1);
}

/* --- Content Section --- */
.content {
    width: 100%;
    line-height: 2.0;
    margin-bottom: 30px;
    padding: 15px;
    background-color: rgba(255, 255, 255, 0.8); /* Improves readability */
    border-radius: 8px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.05);
}

.content .paragraph {
    font-size: 16px;
    margin: 10px 0;
    padding: 0;
    text-align: right;
}

.content .paragraph b,
.content .paragraph strong {
    font-weight: bold;
    color: #2a5298;
    min-width: 140px;
    display: inline-block;
}

/* Red Alerts */
.red {
    color: #d90429;
    font-weight: bold;
    font-size: 16px;
    margin: 12px 0;
    padding: 8px;
    background-color: #fff5f5;
    border-right: 3px solid #d90429;
    border-radius: 4px;
    text-align: right;
    direction: rtl;
}

/* --- Signature Block --- */
.signature {
    width: 100%;
    text-align: right;
    direction: ltr;
    margin-top: auto; /* Push to bottom if using flex column */
    padding-top: 20px;
    border-top: 1px dashed #ccc;
}

.signature .paragraph {
    font-size: 18px;
    font-weight: bold;
    margin: 5px 0;
    padding: 0;
}

body {
  margin: 2cm;
  background: #fff;
  color: #000;
  /* Add print-specific settings */
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
  color-adjust: exact;
}

.form-container {
  max-width: 21cm;
  margin: 0 auto;
  /*border: 1px solid #ccc;*/
  /*padding: 1.5cm;*/
  /*box-sizing: border-box;*/
  /* Ensure container stays within page */
  page-break-inside: avoid;
  break-inside: avoid;
}

.header-table,
.header-table th,
.header-table td {
  border: none !important;
  border-collapse: collapse;
  padding: 0;
  margin: 0;
}

/* Optional: remove spacing if using border-spacing */
.header-table {
  border-spacing: 0;
}


.logo-cell {
  width: 100px;
  vertical-align: middle;
  text-align: left;
  padding: 5px;
}

.title-cell {
  vertical-align: middle;
  text-align: center;
  padding: 5px 15px;
}

.info-cell {
  width: 200px;
  vertical-align: middle;
  text-align: right;
  padding: 5px;
}

.logo {
  width: 100px;
  height: 100px;
  display: block;
}

.header-title {
  font-weight: 600;
  font-size: 0.9rem;
  margin-top: 40px;
}

.header-right {
  font-size: 0.9rem;
  font-weight: 600;
  line-height: 1.3;
  vertical-align: middle;
  text-align: right;
  margin-top: 30px;

}
table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 0.5cm;
  /* Important for table borders in print */
  border: 1px solid #888;
  page-break-inside: avoid;
  break-inside: avoid;
}

th,
td {
  border: 1px solid #888; /* Add for print */
  padding: 0.1cm;
  text-align: center;
  vertical-align: middle; /* Changed from center to middle */
  font-size: 0.6rem;
  max-width: 350px;
  /* Ensure borders print */
  -webkit-print-color-adjust: exact;
}

th {
  background-color: #d0e0f0; /* Important for print */
  font-weight: 600;
  text-align: center;
  /* Force background color in print */
  -webkit-print-color-adjust: exact;
}

.row-header {
  background-color: #d0e0f0;
  font-weight: 600;
  text-align: center;
  -webkit-print-color-adjust: exact;
}

.no-column {
  width: 0.1cm;
  text-align: center;
}

.footer-section {
  margin-top: 1cm;
  border-top: 1px solid #888;
  padding-top: 0.5cm;
  page-break-before: avoid;
  break-before: avoid;
}

.signature-row {
  display: flex;
  justify-content: space-between;
  margin-top: 0.1cm;
  page-break-inside: avoid;
  break-inside: avoid;
}

.signature-box {
  width: 30%;
  text-align: center;
  vertical-align: top;
  border: none;
  font-size: 12px;
  display: inline-block; /* Fix for vertical-align */
}
.signature-stamp-container {
    position: relative;
    display: inline-block;
    min-width: 200px;
}

.signature-wrapper {

    display: inline-block;
    width:100px;
}

.signature {
    height: 100px;
    width: 100px;
    object-fit: contain;
    display: block;
}

.stamp-wrapper {
    position: absolute;
    top: 30px;
    width:200px;
    /* slightly higher for better overlap */
    right: 30px;
    /* adjust to fine-tune placement */
    z-index: 2;
    pointer-events: none;
    /* prevents stamp from blocking text selection/print */
}

.stamp {
    width: 100px;
    height: 100px;
    object-fit: contain;
    background: transparent !important;
    border: none !important;
    border-radius: 0 !important;
    /* let the image's own shape define it */
    box-shadow: none !important;
    /* Optional: realistic slight rotation */
    transform: rotate(-20deg);
}

.note-box {
  margin-top: 0.5cm;
  padding: 0.5cm;
